# D2 es donde la PRIMARIA se entrega: C4 deja su coeficiente por canal y D2 le
# aplica la misma cadena que al compañero (lambda, escala de flujo, presupuesto
# de sistematicos). Lo copiado es esa cadena entera, desde la lectura de los QC
# que la fijan hasta el producto calibrado, porque es lo que se querria tocar
# para preguntarse «¿cuanto de la barra de error es cada cosa?».
#
# Y ademas viaja la extraccion por apertura de A3: la seccion del espectro POR
# OBSERVACION mide la primaria en cada cubo por exposicion, y esa medida tiene
# que ser la misma que hace la cadena en A3, no una reimplementacion. Las dos
# excepciones (`VerificationError`, `TelluricError`) viajan por lo mismo que en
# A3: las levantan las funciones copiadas y el test solo mira `FunctionDef`.
