            "    #   .../raw_reduction/products/<receta>/DATACUBE_FINAL.fits  (antiguas)\n"
            "    candidatos = [r['pre'].parent.parent / 'sof',\n"
            "                  r['pre'].parent.parent.parent / 'sof',\n"
            "                  r['pre'].parent.parent / 'cubes' / 'sof']\n"
