            "modelo son directamente comparables y lo que se ve entre ellos es error de modelo, "
            "no diferencia entre dos estimadores de continuo.\n\n"
            "- **negro** — `flujo / mscal`, el dato sin corregir.\n"
            "- **naranja** — `mtrans`, la transmisión modelada: **las líneas que molecfit dice "
            "que hay**.\n\n"
            "Solo se dibuja dentro de los rangos ajustados (`mrange > 0`), que es donde el "
            "modelo existe. El `rms` anotado en cada panel es el del dato menos el modelo: es la "
            "cifra que dice si ese ajuste, en esa banda, describe la observación.\n\n"
            "**Qué mirar, por orden.** Primero si el modelo sigue la **envolvente** de la banda "
            "—el núcleo profundo y la subida— que es lo que fija la columna de O₂. Después, y es "
            "lo que se escapa a simple vista, si reproduce la **amplitud de los dientes**: son "
            "líneas que MUSE **no resuelve**, así que su profundidad aparente la fija el núcleo "
