            "# fuera de ese radio, medida sobre el cubo grande de A2.\n"
            "from musepipe.growth_curve import load_run_growth_curve, factor_at_wavelengths\n"
            "GC = load_run_growth_curve(SD)\n"
            "if GC is None:\n"
            "    print('\\n[sin stages/growth_curve_qc.json: A2 no lo midió en este run;'\n"
            "          ' `python scripts/measure_growth_curve.py --run-id <RUN> --write-run-product`]')\n"
            "    FACT = None\n"
            "else:\n"
            "    FACT = np.asarray(factor_at_wavelengths(GC, np.asarray(LAMBDAS, float)), float)\n"
