            "    _hE = int(np.ceil(float(GC['r_last_complete_annulus_px'])))\n"
            "    _nE = 2 * _hE + 1\n"
            "    _yE, _xE = np.indices((_nE, _nE), dtype=float)\n"
            "    _rE = np.hypot(_yE - _hE, _xE - _hE)\n"
            "    RADIOS_EXT = np.arange(0.5, _hE + 0.5, 1.0)\n"
            "    CRECE_EXT = {}\n"
            "    for _w in LAMBDAS:\n"
            "        _pE = evaluate_psf_model(PSF_MODEL, _w, _yE - _hE, _xE - _hE)\n"
            "        CRECE_EXT[_w] = np.array([np.nansum(_pE[_rE <= _r]) for _r in RADIOS_EXT])\n"
            "    print(f'\\n--- medido sobre el cubo de A2 ({GC[\"r_last_complete_annulus_px\"]:.0f} px'\n"
            "          f' de último anillo completo, rango de ajuste {GC[\"fit_range_px\"]} px)')\n"
            "    print(f'  {\"λ[Å]\":>8s} {\"F_tot/F(<25)\":>13s} {\"25 px ES el\":>13s}'\n"
