            "        # que el total empírico vale `_f` en esas mismas unidades.\n"
            "        _c = CRECE_EXT[_w]\n"
            "        _r100 = float(np.interp(_f, _c, RADIOS_EXT)) if _c.max() >= _f else np.nan\n"
