            "def _rango(indices, margen=1.25):\n"
            "    \"\"\"Escala simétrica que cubre los paneles pedidos, en unidades de σ.\"\"\"\n"
            "    vals = np.concatenate([paneles[i][4][np.isfinite(paneles[i][4])] for i in indices])\n"
            "    lo, hi = np.percentile(vals, [1, 99])\n"
            "    centro = 0.5 * (lo + hi); semi = max(hi - centro, centro - lo) * margen\n"
            "    return centro - semi, centro + semi\n\n"
            "ESCALAS = [('escala del COMPAÑERO', _rango([0])),\n"
            "           ('escala de los CONTROLES', _rango([1, 2, 3]))]\n"
            "for titulo, (y0, y1) in ESCALAS:\n"
            "    fig, axes = plt.subplots(len(paneles), 1, figsize=(11, 2.3 * len(paneles)),\n"
