            "    for ax_i, (nombre, pa, _pos, wbc, fbc, ebc, color) in zip(np.atleast_1d(axes), paneles):\n"
            "        for lo, hi in BAD_WINDOWS_A:\n"
            "            ax_i.axvspan(lo, hi, color='0.85', zorder=0)\n"
