            "def _mapa(valores):\n"
            "    \"\"\"Los píxeles dispersos de la ventana, de vuelta a una imagen.\"\"\"\n"
            "    m = np.full((wy.max() - wy.min() + 1, wx.max() - wx.min() + 1), np.nan)\n"
